ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS category text,
  ADD COLUMN IF NOT EXISTS spec text,
  ADD COLUMN IF NOT EXISTS features text,
  ADD COLUMN IF NOT EXISTS gallery text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS origin_price text,
  ADD COLUMN IF NOT EXISTS stock_note text;

DELETE FROM public.products p
WHERE NOT EXISTS (SELECT 1 FROM public.order_items oi WHERE oi.product_id = p.id);

INSERT INTO public.products (slug, name, subtitle, category, summary, description, spec, features, price, origin_price, stock, stock_note, image_url, gallery, sort_order, is_active) VALUES
('junco-classic-20g','EI JUNCO CLASSIC 20g','준코 클래식 20g','EI JUNCO CLASSIC',
 '1995년 출시 이후 사랑받아 온 최고급 수제 세안 미용비누. 휴대와 체험용으로 좋은 20g 사이즈입니다.',
 E'JUNCO CLASSIC은 1995년부터 판매되어 온 최고급 수제 세안 미용비누로, "일본 제일의 비누 장인"이라 불리는 미용비누 장인 이시노 에이이치의 가장 대표적인 작품입니다.\n\nJUNCO CLASSIC은 세안과 동시에 미용액이 피부를 촉촉하게 감싸주는 이상적인 세안 비누입니다.\n\n민감한 피부부터 피부 나이가 신경 쓰이는 분까지, 폭넓은 연령대의 여성들에게 지지를 받아 왔습니다.\n\n피부 본래의 아름다움을 깨우는 토르말린을 비롯해 보습·유연·미백 등에 뛰어난 30종 이상의 천연 성분을 배합했습니다.\n\n동봉된 거품망을 사용하면 곱고 탄력 있는 크림 같은 거품을 만들 수 있습니다.\n\n2017년 5월 9일, 본 제품은 일본식품분석센터의 식품 안전 검사에도 합격했습니다.',
 '<세안용 비누> 표준 중량 20g / 와쿠네리(枠練) 제법 / 전용 거품망 포함 / 일본산 (MADE IN JAPAN)',
 '감초 추출물, 인삼 추출물 등 다양한 한방 추출물이 들어간 이상적인 세안 비누입니다. 한방 성분으로 보습·유연·미백 등의 효과도 기대할 수 있습니다.',
 10000,'1,058엔',30,'재고 문의',
